// batch75: valueWithChangeEvent + reactions/autorun — data-driven from
// batch75_truth.json (truth generated by Node vm against real TS source).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/base.dart'
    show IObservableWithChange, IObserver, IReader;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/changeTracker.dart'
    show IChangeContext, IChangeTracker;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/debugName.dart'
    show DebugNameDataLike;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/commonFacade/deps.dart'
    show Event, IValueWithChangeEvent;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/observableValue.dart'
    as ov;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/reactions/autorun.dart'
    as au;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/utils/valueWithChangeEvent.dart'
    as vwce;
import 'package:semi_design_flutter/src/monaco/base/common/lifecycle.dart'
    show DisposableStore, IDisposable, toDisposable;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch75_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

/// Simple event emitter matching the callable Event<T> typedef.
class _Event<T> {
  final List<void Function([Object?])> _listeners = <void Function([Object?])>[];
  late final Event<Object?> event = (dynamic listener, [dynamic thisArgs, dynamic disposables]) {
    void Function([Object?]) l = listener as void Function([Object?]);
    if (thisArgs != null) {
      final captured = thisArgs;
      final base = l;
      l = ([arg]) => base([captured]);
    }
    _listeners.add(l);
    return toDisposable(() => _listeners.remove(l));
  };

  void fire([Object? arg]) {
    for (final l in List<void Function([Object?])>.from(_listeners)) {
      l(arg);
    }
  }
}

class _PlainValue<T> implements IValueWithChangeEvent<T> {
  _PlainValue(this.value, this.onDidChange);
  @override
  T value;
  @override
  final Event<void> onDidChange;
}

/// Observer that records handleChange values (no begin/end bookkeeping needed).
class _ChangeObserver implements IObserver {
  _ChangeObserver(this.onChange);
  final void Function() onChange;
  @override
  void beginUpdate<T>(covariant IObservableWithChange<T, Object?> o) {}
  @override
  void endUpdate<T>(covariant IObservableWithChange<T, Object?> o) {}
  @override
  void handleChange<T, C>(covariant IObservableWithChange<T, C> o, C change) =>
      onChange();
  @override
  void handlePossibleChange<T>(covariant IObservableWithChange<T, Object?> o) {}
}

void main() {
  group('batch75 valueWithChangeEvent', () {
    final t = _truth()['valueWithChangeEvent'] as Map<String, dynamic>;

    test('ValueWithChangeEventFromObservable wraps and round-trips', () {
      final obs = ov.observableValue<int, Object?>('v', 10);
      final wrapped = vwce.ValueWithChangeEventFromObservable<int>(obs);
      expect(wrapped.value, t['value']);
      expect(identical(wrapped.observable, obs), t['observableSame']);
      expect(
        identical(
          vwce.observableFromValueWithChangeEvent<int>(null, wrapped),
          obs,
        ),
        t['roundTripSame'],
      );
      expect(wrapped.onDidChange, isA<Function>());
    });

    test('observableFromValueWithChangeEvent builds from plain event', () {
      final emitter = _Event<Object?>();
      final onDidChange = emitter.event;
      final plain = _PlainValue<int>(7, onDidChange);

      final observable = vwce.observableFromValueWithChangeEvent<int>(
        null,
        plain,
      );
      expect(observable.get(), t['fromPlain']['initialPlain']);

      final seen = <int>[];
      observable.addObserver(_ChangeObserver(() => seen.add(observable.get())));

      // First fire only fills the cache (no change) in real source.
      emitter.fire();
      expect(observable.get(), t['fromPlain']['afterFirst']);

      // Change underlying value + fire -> change observed.
      plain.value = 9;
      emitter.fire();
      expect(observable.get(), t['fromPlain']['final']);
      expect(seen, <int>[9]);
      expect(seen, t['fromPlain']['seen']);
    });
  });

  group('batch75 autorun', () {
    final t = _truth()['autorun'] as Map<String, dynamic>;

    test('autorun runs immediately, re-runs on change, stops on dispose', () {
      final values = <int>[];
      final obs = ov.observableValue<int, Object?>('x', 1);
      final d = au.autorun((reader) {
        values.add(reader.readObservable(obs));
      });
      expect(values, t['initial']);
      obs.set(2, null, null);
      expect(values, t['afterSet']);
      d.dispose();
      obs.set(3, null, null);
      expect(values, t['afterDispose']);
    });

    test('autorunOpts with debugName', () {
      final values = <String>[];
      final obs = ov.observableValue<String, Object?>('y', 'a');
      au.autorunOpts(
        DebugNameDataLike(owner: null, debugName: 'named'),
        (reader) => values.add(reader.readObservable(obs)),
      );
      obs.set('b', null, null);
      expect(values, t['opts']['values']);
    });

    test('autorunHandleChanges delivers tracker summaries', () {
      final summaries = <Map<String, Object?>>[];
      final tracker = _SummarizingTracker();
      final obs = ov.observableValue<int, Object?>('z', 0);
      au.autorunHandleChanges<Map<String, Object?>>(
        au.AutorunHandleChangesOpts<Map<String, Object?>>(
          owner: null,
          debugName: 'hc',
          changeTracker: tracker,
        ),
        (reader, summary) {
          summaries.add(Map<String, Object?>.from(summary));
          reader.readObservable(obs);
        },
      );
      obs.set(5, null, 'delta');
      expect(summaries.length, (t['handleChanges']['summaries'] as List).length);
      expect(summaries[0]['n'], t['handleChanges']['summaries'][0]['n']);
      expect(summaries[1]['n'], t['handleChanges']['summaries'][1]['n']);
      expect(summaries[1]['changes'], t['handleChanges']['summaries'][1]['changes']);
    });

    test('autorunWithStore reuses one store across runs', () {
      final stores = <DisposableStore>[];
      final obs = ov.observableValue<int, Object?>('ws', 0);
      au.autorunWithStore((reader, store) {
        stores.add(store);
        reader.readObservable(obs);
      });
      obs.set(1, null, null);
      expect(stores.length, t['withStore']['runCount']);
      expect(identical(stores[0], stores[1]), t['withStore']['sameStore']);
    });

    test('autorunDelta passes lastValue/newValue', () {
      final args = <Map<String, Object?>>[];
      final obs = ov.observableValue<int, Object?>('d', 3);
      au.autorunDelta<int>(obs, (a) {
        args.add(<String, Object?>{
          'last': a.lastValue,
          'now': a.newValue,
        });
      });
      obs.set(4, null, null);
      final truthArgs = t['delta']['args'] as List;
      expect(args.length, truthArgs.length);
      for (int i = 0; i < truthArgs.length; i++) {
        expect(args[i]['now'], truthArgs[i]['now']);
        expect(args[i]['last'], truthArgs[i]['last']);
      }
    });

    test('autorunIterableDelta reports adds/removes by unique id', () {
      final args = <Map<String, Object?>>[];
      final items = ov.observableValue<List<Map<String, Object?>>, Object?>(
        'arr',
        <Map<String, Object?>>[
          <String, Object?>{'id': 'a', 'v': 1},
          <String, Object?>{'id': 'b', 'v': 2},
        ],
      );
      au.autorunIterableDelta<Map<String, Object?>>(
        (reader) => reader.readObservable(items),
        (a) {
          args.add(<String, Object?>{
            'added': a.addedValues.map((x) => x['id']).toList(),
            'removed': a.removedValues.map((x) => x['id']).toList(),
          });
        },
        (x) => x['id'] as Object,
      );
      // same ids, different value -> no add/remove
      items.set(<Map<String, Object?>>[
        <String, Object?>{'id': 'a', 'v': 9},
        <String, Object?>{'id': 'b', 'v': 2},
      ], null, null);
      // remove b
      items.set(<Map<String, Object?>>[
        <String, Object?>{'id': 'a', 'v': 9},
      ], null, null);

      final truthArgs = t['iterableDelta']['args'] as List;
      expect(args.length, truthArgs.length);
      for (int i = 0; i < truthArgs.length; i++) {
        expect(args[i]['added'], truthArgs[i]['added']);
        expect(args[i]['removed'], truthArgs[i]['removed']);
      }
    });

    test('autorunPerKeyedItem sets up once per key and updates cell values', () {
      final setups = <String>[];
      final cellValues = <List<Object?>>[];
      final items = ov.observableValue<List<Map<String, Object?>>, Object?>(
        'items',
        <Map<String, Object?>>[
          <String, Object?>{'id': 'k1', 'v': 1},
          <String, Object?>{'id': 'k2', 'v': 2},
        ],
      );
      au.autorunPerKeyedItem<Map<String, Object?>, String>(
        items,
        (item) => item['id'] as String,
        (key, value, store) {
          setups.add(key);
          au.autorun((reader) {
            cellValues.add(<Object?>[key, reader.readObservable(value)]);
          });
        },
      );
      items.set(<Map<String, Object?>>[
        <String, Object?>{'id': 'k1', 'v': 10},
        <String, Object?>{'id': 'k2', 'v': 2},
      ], null, null);

      expect(setups, t['perKeyedItem']['setups']);
      final truthCells = t['perKeyedItem']['cellValues'] as List;
      expect(cellValues.length, truthCells.length);
      for (int i = 0; i < truthCells.length; i++) {
        expect(cellValues[i][0], truthCells[i][0]);
        expect((cellValues[i][1] as Map)['id'], truthCells[i][1]['id']);
        expect((cellValues[i][1] as Map)['v'], truthCells[i][1]['v']);
      }
    });

    test('autorunSelfDisposable safe on first run and on reaction', () {
      int selfCount = 0;
      bool selfDisposed = false;
      au.autorunSelfDisposable((reader) {
        selfCount++;
        if (!selfDisposed) {
          selfDisposed = true;
          reader.dispose();
        }
      });
      bool reactDisposed = false;
      final reactObs = ov.observableValue<int, Object?>('ro', 0);
      au.autorunSelfDisposable((reader) {
        reader.readObservable(reactObs);
        if (reactObs.get() == 1 && !reactDisposed) {
          reactDisposed = true;
          reader.dispose();
        }
      });
      reactObs.set(1, null, null);
      expect(selfCount, t['selfDisposable']['firstRunCount']);
      expect(selfDisposed, t['selfDisposable']['disposedFirst']);
      expect(reactDisposed, t['selfDisposable']['disposedReaction']);
    });

    test('registerAutorunSelfDisposable registers into store', () {
      int stored = 0;
      final fakeStore = _CountingStore(() => stored++);
      au.registerAutorunSelfDisposable(fakeStore, (reader) {});
      expect(stored, t['registerSelfDisposable']['stored']);
    });
  });
}

class _SummarizingTracker implements IChangeTracker<Map<String, Object?>> {
  @override
  Map<String, Object?> createChangeSummary(Map<String, Object?>? previous) =>
      <String, Object?>{
        'n': (previous?['n'] as int? ?? 0) + 1,
        'changes': <Object?>[],
      };

  @override
  void beforeUpdate(IReader reader, Map<String, Object?> change) {}

  @override
  bool handleChange(IChangeContext ctx, Map<String, Object?> change) {
    (change['changes'] as List).add(ctx.change);
    return true;
  }
}

class _CountingStore extends DisposableStore {
  _CountingStore(this.onAdd);
  final void Function() onAdd;
  @override
  T add<T extends IDisposable>(T value) {
    onAdd();
    return super.add(value);
  }
}
